# =============================================================== B10: THE RESAMPLER

#: ⭐ B10. THE ONE CANONICAL RESAMPLER. §4 declares that a single resampler with
#: declared parameters is used everywhere and recorded on every row. It did not
#: previously exist and the fuzz called torchaudio at defaults. It exists now,
#: and `fuzz_gate4_lib.py` and Stage 1 both call THIS.
RESAMPLE = {
    "impl": "torchaudio.functional.resample",
    "resampling_method": "sinc_interp_kaiser",
    "lowpass_filter_width": 64,
    "rolloff": 0.9475937167399596,
    "beta": 14.769656459379492,
}


def resample(x, sr_from, sr_to):
    """The single resampling path. Every rate change in Gate 4 goes through here.

    Returns (signal, provenance) - the provenance dict is recorded on the row so
    a reader can see exactly which filter produced the number.
    """
    import torchaudio
    prov = dict(RESAMPLE, sr_from=int(sr_from), sr_to=int(sr_to))
    if int(sr_from) == int(sr_to):
        return _flat(x), dict(prov, applied=False)
    t = torch.from_numpy(_flat(x)).float().reshape(1, -1)
    y = torchaudio.functional.resample(
        t, int(sr_from), int(sr_to),
        lowpass_filter_width=RESAMPLE["lowpass_filter_width"],
        rolloff=RESAMPLE["rolloff"],
        resampling_method=RESAMPLE["resampling_method"],
        beta=RESAMPLE["beta"])
    return y.reshape(-1).numpy().astype(np.float64), dict(prov, applied=True)


