    ro, err = spectral_rolloff_hz(estimate, sr)
    if ro is None:
        return {"state": "NOT COMPARABLE - OUTSIDE VALIDATED SUPPORT",
                "in_support": False, "rolloff_hz": None, "reason": err,
                "threshold_hz": SUPPORT_MIN_ROLLOFF_HZ,
                "fraction": SUPPORT_FRACTION}
    ok = ro >= SUPPORT_MIN_ROLLOFF_HZ
    return {
        "state": "MEASURED" if ok else "NOT COMPARABLE - OUTSIDE VALIDATED SUPPORT",
        "in_support": bool(ok), "rolloff_hz": ro,
        "threshold_hz": SUPPORT_MIN_ROLLOFF_HZ, "fraction": SUPPORT_FRACTION,
        "derived_from": "held-out calibration, 66 cells, 6 states x 11 "
                        "band-limits; strictly above the highest G6-failing "
                        "roll-off (2531 Hz); 0 false admissions",
    }

