def _resolve_tol(length_tol):
    """F4. None / NOT ESTABLISHED stays UNKNOWN. It never becomes 0."""
    if length_tol is None or length_tol == TOL_NOT_ESTABLISHED:
        raise Domain("LENGTH TOLERANCE NOT ESTABLISHED for this arm - no "
                     "samples_per_unit in the frozen Gate 2 matrix. An "
                     "unmeasured tolerance is NOT silently treated as 0.")
    return int(length_tol)

UNKNOWN = None


class Domain(Exception):
    """Input outside a metric's declared domain. Callers get UNKNOWN + a reason,
    never a number computed from an inadmissible input."""


# ---------------------------------------------------------------- helpers

def _flat(x):
    if torch.is_tensor(x):
        x = x.detach().float().cpu().numpy()
    return np.asarray(x, dtype=np.float64).reshape(-1)


def _check(x, name, min_samples=2):
    x = _flat(x)
    if x.size < min_samples:
        raise Domain(f"{name}: {x.size} samples, need >= {min_samples}")
    if not np.isfinite(x).all():
        raise Domain(f"{name}: contains NaN or inf")
    return x


def _pair(a, b, length_tol):
    """⭐ B5. Validate a pair AND ITS LENGTHS. A length mismatch beyond the
    declared tolerance is a FAILURE, not something to trim away.

    The previous implementation compared `min(len_a, len_b)` samples, so a
    signal 256 samples short scored EXACTLY IDENTICAL to the reference. Under
    §8.3 the offline quality of `vocos_mel24` and `griffinlim` is declared
    admissible; those two arms lose 256 samples per chunk, and this defect would
    have reported that loss as a perfect reconstruction.
    """
    a = _check(a, "reference")
    b = _check(b, "estimate")
    delta = int(b.size - a.size)
    if abs(delta) > int(length_tol):
        raise Domain(f"LENGTH MISMATCH: estimate is {delta:+d} samples vs "
                     f"reference (tolerance {length_tol}). A length failure is "
                     f"never absorbed into a quality score.")
    if delta:
        n = min(a.size, b.size)
        a, b = a[:n], b[:n]
    return a, b, delta


def _result(value, tier, note=None, **extra):
    d = {"value": value, "tier": tier,
         "state": "MEASURED" if value is not None else "UNKNOWN"}
    if note:
        d["note"] = note
    d.update(extra)
    return d


def _fail(tier, reason, **extra):
    d = {"value": UNKNOWN, "tier": tier, "state": "UNKNOWN", "note": reason}
    if reason.startswith("LENGTH TOLERANCE NOT ESTABLISHED"):
        d["state"] = "NOT ESTABLISHED"
    elif reason.startswith("LENGTH MISMATCH"):
        d["state"] = "LENGTH FAILURE"
    d.update(extra)
    return d


def _win_hop(sr, win_ms, hop_ms, max_bin_hz=None):
    """M2. Exact sample counts for a declared physical duration.

    D1: when `max_bin_hz` is given the FFT is padded until the bin width meets
    that DECLARED HERTZ resolution. Padding changes no analysis window - `win`
    and `hop` are unchanged - it only refines the frequency grid, which is what
    stops a mel band from capturing zero bins.
    """
    win = max(16, int(round(win_ms * sr / 1000.0)))
    hop = max(1, int(round(hop_ms * sr / 1000.0)))
    n_fft = 1 << int(np.ceil(np.log2(win)))     # padding only; window unchanged
    if max_bin_hz:
        while sr / n_fft > max_bin_hz:
            n_fft <<= 1
    return win, hop, n_fft


def _stft_mag(x, sr, win_ms, hop_ms, max_bin_hz=None):
    win, hop, n_fft = _win_hop(sr, win_ms, hop_ms, max_bin_hz)
    t = torch.from_numpy(x).float()
    S = torch.stft(t, n_fft=n_fft, hop_length=hop, win_length=win,
                   window=torch.hann_window(win), return_complex=True, center=True)
    return S.abs().numpy(), n_fft, win, hop


def _floor_to(ref_mag, *mags):
    """M3. Clamp every magnitude at SPEC_FLOOR_DB relative to the REFERENCE's own
    peak, so a band with no energy is a bounded distance from one that has some."""
    peak = float(ref_mag.max()) if ref_mag.size else 0.0
    floor = max(peak * (10.0 ** (SPEC_FLOOR_DB / 20.0)), EPS)
    return [np.maximum(m, floor) for m in mags]


def gain_match(ref, est):
    """M5 / D7. RMS-domain gain match. PHASE-ROBUST.

    THE TIME-DOMAIN LEAST-SQUARES VERSION COLLAPSED ON THIS STUDY'S OWN SIGNALS.
    g = <ref,est>/<est,est> is an inner product, so it measures phase agreement
    as much as level. MEASURED: g = 1.000 on an identical signal and 0.500 for a
    x2 gain (both correct), but 0.394 for a 16-SAMPLE SHIFT and -0.0675 for a
    PHASE-RANDOMISED estimate - a NEGATIVE gain applied to a spectrally faithful
    reconstruction. Section 5.3 declares that only the gain-matched variant may
    rank, so the declared fallback was unusable on exactly the phase-incoherent
    output every neural decoder produces.

    The RMS ratio is invariant to phase and to time shift, which is what a level
    match must be.
    """
    re_ = float(np.sqrt((ref ** 2).mean()))
    ee = float(np.sqrt((est ** 2).mean()))
    if ee <= EPS:
        return est.copy(), 1.0
    g = re_ / ee
    return est * g, g


# =============================================================== B4: THE FLOOR

def rate_chain_floor(master, sr_master, sr_in, sr_out, metric_fn,
                     common_sr=None):
    """⭐ B4. The ONLY defensible decoder-free floor: the arm's OWN rate chain,
    with the codec removed.

    ⛔ THE DELETED FLOOR AND WHY. The previous floor resampled 48k -> 24k -> 48k
    and compared the result against the UNTOUCHED full-band reference. That
    band-limits one side and leaves the other alone - a transformation §4 NEVER
    PERFORMS, because §4 always brings both sides to the same rate. It produced
    thresholds LARGER than the distance to a different person's voice (mcd
    1102.7 vs 920.1) and 99.1% of the distance to digital silence, which made
    §11.1 condition 5 arithmetically unsatisfiable by any pair of arms.

    What this computes instead, per arm and per denominator:

      reference : master -> sr_out                (what the comparison uses)
      null route: master -> sr_in -> sr_out       (the arm's chain, NO CODEC)

    and under REFERENCE-COMMON both are additionally taken to `common_sr`. The
    difference between them is EXACTLY the resampling the arm's own chain
    imposes and nothing else, so a measured difference smaller than this floor
    is not attributable to the decoder.
    """
    m = _flat(master)
    ref, p1 = resample(m, sr_master, sr_out)
    mid, p2 = resample(m, sr_master, sr_in)
    null, p3 = resample(mid, sr_in, sr_out)
    if common_sr is not None:
        ref, p4 = resample(ref, sr_out, common_sr)
        null, p5 = resample(null, sr_out, common_sr)
        sr_eval = common_sr
    else:
        sr_eval = sr_out
    n = min(ref.size, null.size)
    out = metric_fn(ref[:n], null[:n], sr_eval)
    return {"floor": out, "sr_eval": int(sr_eval),
            "chain": {"reference": [int(sr_master), int(sr_out)],
                      "null_route": [int(sr_master), int(sr_in), int(sr_out)],
                      "common_sr": (int(common_sr) if common_sr else None)},
            "resampler": RESAMPLE}


# =============================================================== B7: ALIGNMENT

def _envelope(x, sr):
    """Short-time RMS envelope on the FRAME grid. PHASE-INVARIANT by construction."""
    win, hop, _ = _win_hop(sr, ENV_WIN_MS, ENV_HOP_MS)
    if x.size < win:
        return np.zeros(0)
    n = 1 + (x.size - win) // hop
    idx = np.arange(win)[None, :] + hop * np.arange(n)[:, None]
    return np.sqrt((x[idx] ** 2).mean(axis=1))


def _envelope_per_sample(x, sr):
    """D3. The SAME RMS envelope, evaluated at EVERY SAMPLE, via cumulative sums.

    Phase-invariant exactly as the frame-grid envelope is - it is the identical
    statistic, simply not decimated. O(n), so refining to sample resolution costs
    one pass rather than one correlation per candidate lag.
    """
    win, _, _ = _win_hop(sr, ENV_WIN_MS, ENV_HOP_MS)
    if x.size < win:
        return np.zeros(0)
    c = np.concatenate([[0.0], np.cumsum(x ** 2)])
    return np.sqrt(np.maximum((c[win:] - c[:-win]) / win, 0.0))


def _refine_delay(a, b, sr, d0, radius):
    """D3. Refine a coarse delay to SAMPLE resolution inside +/- `radius`.

    THE DEFECT THIS REPAIRS. `delay_samples = round(lag_frames * hop)` could only
    ever report MULTIPLES OF ONE ENVELOPE HOP (5 ms). Measured on the shipped
    code, with mcd - the SOLE ranking metric - charged for the residual:

        sr=16k  true  40 -> reported   0, residual  40 -> mcd 119.0 = 49% of rung
        sr=16k  true 120 -> reported  80, residual  40 -> mcd 119.1 = 50% of rung
        sr=48k  true 120 -> reported   0, residual 120 -> mcd 114.6 = 82% of rung

    The fuzz could not see it because its tolerance was set EQUAL to one hop, so
    `delayed_100 -> 0` was recorded as `delay_recovered: True`.

    Arms may differ by less than one damage rung, so an alignment residual of
    this size is the same order as the effect being ranked.
    """
    ea = _envelope_per_sample(a, sr)
    eb = _envelope_per_sample(b, sr)
    if ea.size < 16 or eb.size < 16:
        return d0, None
    ea = ea - ea.mean()
    eb = eb - eb.mean()
    n = min(ea.size, eb.size)
    ea, eb = ea[:n], eb[:n]
    N = 1
    while N < 2 * n:
        N *= 2
    cc = np.fft.irfft(np.fft.rfft(eb, N) * np.conj(np.fft.rfft(ea, N)), N)
    lags = np.arange(d0 - radius, d0 + radius + 1)
    vals = np.array([cc[l % N] for l in lags])
    k = int(np.argmax(vals))
    den = float(np.sqrt((ea ** 2).sum() * (eb ** 2).sum()))
    return int(lags[k]), float(vals[k]) / max(den, EPS)


def alignment(source_at_out_sr, out, sr):
    """⭐ B7. ENVELOPE alignment. Phase-invariant.

    ⛔ WHAT WAS WRONG AND WHY IT MATTERED. The previous gate cross-correlated RAW
    WAVEFORMS through `gate3_lib.estimate_delay` and required r >= 0.50. §5.1 of
    the pre-registration already states that neural codecs DO NOT PRESERVE
    PHASE - so that gate measured phase coherence, and recomputing it against
    the frozen `gate3_matrix.json` calibrations rejects 8 of 19 arms:

        all six FocalCodec  r = 0.083 - 0.197
        vocos_mel24         r = 0.259
        griffinlim          r = 0.364
        mimi_q8 (PRIMARY)   r = 0.513  - 2.6% above the line

    Those are precisely the architectures that RESYNTHESISE phase. The gate's
    missingness was therefore correlated with the estimand: tier-B metrics would
    have been unavailable for exactly the arms whose spectral fidelity was the
    question, Route B would have had no valid tier-B pair at all, and Q9's floor
    would never have received a tier-B number.

    THE REPLACEMENT measures agreement of the ENERGY ENVELOPE, which is what a
    frame-alignment actually needs. A decoder may reconstruct a waveform with
    entirely different phase and still place the same energy at the same time;
    that is a faithful reconstruction and the gate must not reject it.
    """
    try:
        a = _check(source_at_out_sr, "source", 1024)
        b = _check(out, "out", 1024)
    except Domain as e:
        return {"state": "ALIGNMENT NOT ESTABLISHED", "reason": str(e),
                "method": "envelope"}

    ea, eb = _envelope(a, sr), _envelope(b, sr)
    if ea.size < 8 or eb.size < 8:
        return {"state": "ALIGNMENT NOT ESTABLISHED",
                "reason": "signal shorter than 8 envelope frames",
                "method": "envelope"}
    n = min(ea.size, eb.size)
    ea, eb = ea[:n] - ea[:n].mean(), eb[:n] - eb[:n].mean()
    hop_s = _win_hop(sr, ENV_WIN_MS, ENV_HOP_MS)[1] / sr
    maxlag = min(int(round(ALIGN_SEARCH_MS / 1000.0 / hop_s)), n - 1)
    if maxlag < 1:
        return {"state": "ALIGNMENT NOT ESTABLISHED",
                "reason": "search window shorter than one envelope hop",
                "method": "envelope"}
    N = 1
    while N < 2 * n:
        N *= 2
    A = np.fft.rfft(ea, N)
    B = np.fft.rfft(eb, N)
    cc = np.fft.irfft(B * np.conj(A), N)
    win = np.concatenate([cc[-maxlag:], cc[:maxlag + 1]])
    k = int(np.argmax(win))
    lag_frames = k - maxlag
    den = float(np.sqrt((ea ** 2).sum() * (eb ** 2).sum()))
    r = float(win[k]) / max(den, EPS)
    coarse = int(round(lag_frames * hop_s * sr))
    hop_samples = int(round(ENV_HOP_MS * sr / 1000.0))
    # D3: refine to SAMPLE resolution within +/- one hop of the coarse estimate.
    delay_samples, r_fine = _refine_delay(a, b, sr, coarse, hop_samples)
    return {
        "method": "envelope+sample_refine", "env_win_ms": ENV_WIN_MS,
        "env_hop_ms": ENV_HOP_MS, "coarse_delay_samples": coarse,
        "refine_radius_samples": hop_samples,
        "resolution_samples": 1,
        "delay_samples": delay_samples, "delay_ms": 1000.0 * delay_samples / sr,
        "envelope_correlation": r, "refined_correlation": r_fine,
        "threshold": ALIGN_MIN_ENV_CORR, "search_window_ms": ALIGN_SEARCH_MS,
        "convention": "positive lag = decoder output LAGS the source",
        "state": "MEASURED" if r >= ALIGN_MIN_ENV_CORR else "ALIGNMENT NOT ESTABLISHED",
    }


def _apply_delay(source, out, delay_samples):
    d = int(delay_samples)
    if d > 0:
        out = out[d:]
    elif d < 0:
        source = source[-d:]
    n = min(source.size, out.size)
    return source[:n], out[:n]


# ================================================================ TIER A

def max_abs_err(full, streamed, length_tol=DEFAULT_LENGTH_TOL):
    """gate_lib.err(), imported verbatim.

    ⛔ DETECTOR, not a severity scale (amendment 6), permanently.
    """
    try:
        a, b, delta = _pair(full, streamed, length_tol)
    except Domain as e:
        return _fail("A", str(e))
    raw, rel = GL.err(torch.from_numpy(a), torch.from_numpy(b))
    return _result(raw, "A", "DETECTOR - never a severity scale (amendment 6)",
                   rel_pct=100.0 * rel, length_delta=delta)


def si_sdr(reference, estimate, length_tol=DEFAULT_LENGTH_TOL):
    """Scale-invariant SDR, dB. Tier A only.

    DECLARED DOMAIN: finite, non-empty, LENGTHS EQUAL within tolerance, and the
    reference carries energy.

    ⚠️ An exact scaled copy has NO FINITE VALUE. That is a property of the
    definition, recorded as `state: DEGENERATE`, not as a number. ⛔ AN ALL-ZERO
    ESTIMATE IS ALSO A SCALED COPY (scale 0) and must NOT be reported as a
    perfect score - it is returned as DEGENERATE with its own reason.
    """
    try:
        r, e, delta = _pair(reference, estimate, length_tol)
    except Domain as ex:
        return _fail("A", str(ex))
    rr = float(r @ r)
    if rr <= EPS:
        return _fail("A", "reference carries no energy", length_delta=delta)
    if float(e @ e) <= EPS:
        d = _fail("A", "estimate is digital silence - si_sdr is degenerate here "
                       "and is NOT a perfect score", length_delta=delta)
        d["state"] = "DEGENERATE"
        return d
    proj = (float(e @ r) / rr) * r
    noise = e - proj
    den = float(noise @ noise)
    if den <= EPS:
        d = _fail("A", "estimate is an exact scaled copy of the reference",
                  length_delta=delta)
        d["state"] = "DEGENERATE"
        return d
    return _result(10.0 * np.log10(float(proj @ proj) / den), "A",
                   length_delta=delta)


def seams(full, streamed, seam_idx, sr, win_ms=5.0, length_tol=DEFAULT_LENGTH_TOL):
    """gate3_lib.seam_metrics(), imported verbatim. §10.6.

    ⚠️ Self-referential. Not a quality ranking between decoders.
    """
    try:
        a, b, delta = _pair(full, streamed, length_tol)
    except Domain as e:
        return _fail("A", str(e))
    out = L3.seam_metrics(torch.from_numpy(a).float(), torch.from_numpy(b).float(),
                          seam_idx, sr, win_ms=win_ms)
    return _result(out, "A", "self-referential - QUALITY COMPARISON NOT ESTABLISHED",
                   length_delta=delta)


# ================================================================ TIER B

def _mel_fb(sr, n_fft):
    """M2. Filterbank over a PHYSICAL frequency range, so band k is the same Hz
    at every sample rate."""
    def hz2mel(f):
        return 2595.0 * np.log10(1.0 + f / 700.0)

    def mel2hz(m):
        return 700.0 * (10.0 ** (m / 2595.0) - 1.0)

    fmax = min(MEL_FMAX_HZ, sr / 2.0)
    pts = mel2hz(np.linspace(hz2mel(MEL_FMIN_HZ), hz2mel(fmax), MCD_N_MELS + 2))
    bins = np.clip(np.floor((n_fft + 1) * pts / sr).astype(int), 0, n_fft // 2)
    fb = np.zeros((MCD_N_MELS, n_fft // 2 + 1))
    for i in range(MCD_N_MELS):
        l, c, r = bins[i], bins[i + 1], bins[i + 2]
        if c > l:
            fb[i, l:c] = np.linspace(0, 1, c - l, endpoint=False)
        if r > c:
            fb[i, c:r] = np.linspace(1, 0, r - c, endpoint=False)
    # D1 GUARD. An empty band pins its energy at a CONSTANT and destroys mcd's
    # gain invariance. It must never be silently tolerated: a band count the
    # frequency grid cannot support is a DOMAIN error, not a small inaccuracy.
    empty = int((fb.sum(axis=1) == 0).sum())
    if empty:
        raise Domain("mel filterbank has %d EMPTY band(s) at sr=%d, n_fft=%d "
                     "(bin width %.2f Hz). An empty band breaks gain invariance "
                     "- see MAX_BIN_HZ." % (empty, sr, n_fft, sr / n_fft))
    return fb


def _cepstra(x, sr, fb, floor):
    S, n_fft, win, hop = _stft_mag(x, sr, FRAME_MS, HOP_MS, MAX_BIN_HZ)
    S = np.maximum(S, floor)
    E = fb @ (S ** 2)
    # D1, belt and braces. The floor is PROPORTIONAL to this signal's own peak
    # band energy, so every band scales with a gain change and c0 removal
    # cancels it exactly. An ABSOLUTE +EPS was the mechanism by which an empty
    # band leaked gain sensitivity into a metric that exists to be
    # gain-invariant.
    mel = np.log(np.maximum(E, float(E.max()) * 1e-10 + EPS))
    n = mel.shape[0]
    k = np.arange(n)
    basis = np.cos(np.pi / n * (k[:, None] + 0.5) * np.arange(MCD_N_CEPS + 1)[None, :])
    return (basis.T @ mel)[1:MCD_N_CEPS + 1]


def mcd(source, out, sr, delay_samples=0, length_tol=DEFAULT_LENGTH_TOL):
    """Mel-cepstral distortion, dB. Lower is closer.

    M2: window declared in ms, mel band declared in Hz.
    M3: spectra floored relative to the reference peak.
    M5: c0 excluded, so a pure gain change does not register as distortion -
        `mcd` is the GAIN-INVARIANT member of the tier-B set by construction.
    """
    try:
        a, b, ldelta = _pair(source, out, _resolve_tol(length_tol))
    except Domain as e:
        return _fail("B", str(e))
    a, b = _apply_delay(a, b, delay_samples)
    win, hop, n_fft = _win_hop(sr, FRAME_MS, HOP_MS, MAX_BIN_HZ)
    if min(a.size, b.size) < win:
        return _fail("B", "shorter than one analysis window")
    # ⭐ The floor is PER SIGNAL here, unlike lsd/ltas. `mcd` drops c0 precisely
    # so that a pure level change is not distortion; a floor taken from the
    # REFERENCE's peak would re-import gain sensitivity through the back door and
    # destroy the one gain-invariant metric in the tier-B set.
    fb = _mel_fb(sr, n_fft)
    fa = max(float(_stft_mag(a, sr, FRAME_MS, HOP_MS, MAX_BIN_HZ)[0].max())
             * (10.0 ** (SPEC_FLOOR_DB / 20.0)), EPS)
    fbb = max(float(_stft_mag(b, sr, FRAME_MS, HOP_MS, MAX_BIN_HZ)[0].max())
              * (10.0 ** (SPEC_FLOOR_DB / 20.0)), EPS)
    ca, cb = _cepstra(a, sr, fb, fa), _cepstra(b, sr, fb, fbb)
    m = min(ca.shape[1], cb.shape[1])
    if m < 1:
        return _fail("B", "no overlapping frames")
    d = ca[:, :m] - cb[:, :m]
    k = (10.0 / np.log(10.0)) * np.sqrt(2.0)
    return _result(float(np.mean(k * np.sqrt((d ** 2).sum(axis=0)))), "B",
                   frames=int(m), window_ms=FRAME_MS, mel_band_hz=[MEL_FMIN_HZ,
                   min(MEL_FMAX_HZ, sr / 2.0)], gain_invariant=True)


def lsd(source, out, sr, delay_samples=0, gain_matched=False,
        length_tol=DEFAULT_LENGTH_TOL):
    """Log-spectral distance, dB RMS. M2 geometry, M3 floor.

    ⚠️ M5: GAIN-SENSITIVE. A pure x2 gain moves it by exactly 20*log10(2).
    Call with `gain_matched=True` for the level-invariant variant. Stage 2
    reports BOTH and the pre-registration declares which one carries a claim.
    """
    try:
        a, b, ldelta = _pair(source, out, length_tol)
    except Domain as e:
        return _fail("B", str(e))
    a, b = _apply_delay(a, b, delay_samples)
    g = 1.0
    if gain_matched:
        b, g = gain_match(a, b)
    win, hop, _ = _win_hop(sr, LSD_WIN_MS, LSD_HOP_MS)
    if min(a.size, b.size) < win:
        return _fail("B", "shorter than one analysis window")
    A, _, _, _ = _stft_mag(a, sr, LSD_WIN_MS, LSD_HOP_MS)
    B, _, _, _ = _stft_mag(b, sr, LSD_WIN_MS, LSD_HOP_MS)
    A, B = _floor_to(A, A, B)
    m = min(A.shape[1], B.shape[1])
    d = 20.0 * (np.log10(A[:, :m]) - np.log10(B[:, :m]))
    return _result(float(np.sqrt((d ** 2).mean())), "B", frames=int(m),
                   window_ms=LSD_WIN_MS, gain_matched=gain_matched, gain=g,
                   gain_invariant=bool(gain_matched))


def mrstft_mag(source, out, sr, delay_samples=0, gain_matched=False,
               length_tol=DEFAULT_LENGTH_TOL):
    """Multi-resolution STFT magnitude distance. M2: resolutions in MILLISECONDS.

    ⚠️ M5: gain-sensitive, and it SATURATES near 1.0 - an all-zero estimate and a
    x2 gain both score ~1.0. Its useful range is below saturation and the
    saturation point is recorded on every row.
    """
    try:
        a, b, ldelta = _pair(source, out, length_tol)
    except Domain as e:
        return _fail("B", str(e))
    a, b = _apply_delay(a, b, delay_samples)
    g = 1.0
    if gain_matched:
        b, g = gain_match(a, b)
    per = {}
    for w_ms, h_ms in zip(MRSTFT_WINS_MS, MRSTFT_HOPS_MS):
        win, _, _ = _win_hop(sr, w_ms, h_ms)
        if min(a.size, b.size) < win:
            continue
        A, _, _, _ = _stft_mag(a, sr, w_ms, h_ms)
        B, _, _, _ = _stft_mag(b, sr, w_ms, h_ms)
        m = min(A.shape[1], B.shape[1])
        num = np.linalg.norm(A[:, :m] - B[:, :m])
        den = max(float(np.linalg.norm(A[:, :m])), EPS)
        per[f"{w_ms:g}ms"] = float(num / den)
    if not per:
        return _fail("B", "shorter than the smallest analysis window")
    return _result(float(np.mean(list(per.values()))), "B", per_resolution=per,
                   gain_matched=gain_matched, gain=g,
                   saturates_at=1.0, gain_invariant=bool(gain_matched))


# ================================================================ TIER C

def ltas_dist(source, out, sr, gain_matched=False,
              length_tol=DEFAULT_LENGTH_TOL, delay_samples=0):
    """Long-term average spectrum distance, dB RMS. Alignment-free.

    M2 geometry, M3 floor.
    ⚠️ M5: GAIN-SENSITIVE (x2 gain moves it 6.02 dB, comparable to a whole damage
    rung). `gain_matched=True` gives the level-invariant variant; both reported.
    """
    try:
        a, b, ldelta = _pair(source, out, length_tol)
    except Domain as e:
        return _fail("C", str(e))
    need = int(MIN_SECONDS_LTAS * sr)
    if min(a.size, b.size) < need:
        return _fail("C", f"shorter than {MIN_SECONDS_LTAS}s")
    # F-minor: LTAS took no delay compensation at all, so a constant algorithmic
    # delay shifted its score one-directionally (-0.4% of a rung at 5 ms, -5.3%
    # at 80 ms, against measured Gate 3 arm delays of 15-36 ms). It is applied
    # here for the same reason every other source-referenced metric applies it.
    a, b = _apply_delay(a, b, delay_samples)
    g = 1.0
    if gain_matched:
        b, g = gain_match(a, b)
    A, _, _, _ = _stft_mag(a, sr, LSD_WIN_MS, LSD_HOP_MS)
    B, _, _, _ = _stft_mag(b, sr, LSD_WIN_MS, LSD_HOP_MS)
    # F3. THE FLOOR IS TAKEN AND APPLIED IN THE SAME DOMAIN.
    #
    # THE DEFECT: `_floor_to(A, A.mean(axis=1), B.mean(axis=1))` measured the
    # floor from the peak of the FULL STFT (24.39 on the calibration file) and
    # applied it to the FRAME-AVERAGED spectrum, whose peak is 2.65 - roughly
    # 10x smaller. The clamp therefore bit an order of magnitude too hard:
    # MEASURED 8 of 257 bins clamped for the reference but 127 of 257 (49.4%)
    # for a 4 kHz band-limited estimate. `ltas_dist` was scoring SPECTRAL
    # SUPPORT, not fidelity - a 4 kHz roll-off reached 89% of the distance to a
    # completely different speaker, and 2 kHz exceeded it by 58%.
    #
    # `lsd` already used the consistent form `_floor_to(A, A, B)`; only this
    # function had the mismatch.
    Am, Bm = A.mean(axis=1), B.mean(axis=1)
    Am, Bm = _floor_to(Am, Am, Bm)
    d = 20.0 * (np.log10(Am) - np.log10(Bm))
    return _result(float(np.sqrt((d ** 2).mean())), "C", gain_matched=gain_matched,
                   gain=g, gain_invariant=bool(gain_matched),
                   floor_domain="frame-averaged spectrum (F3)")


def bandwidth_khz(x, sr):
    """Highest frequency below which BANDWIDTH_FRACTION of band energy lies.

    ⚠️ SANITY INSTRUMENT, NEVER A QUALITY SCORE. Never ranked.
    """
    try:
        a = _check(x, "signal")
    except Domain as e:
        return _fail("C", str(e))
    if a.size < int(MIN_SECONDS_LTAS * sr):
        return _fail("C", f"shorter than {MIN_SECONDS_LTAS}s")
    S = _stft_mag(a, sr, LSD_WIN_MS, LSD_HOP_MS)[0].mean(axis=1) ** 2
    tot = S.sum()
    if tot <= EPS:
        return _fail("C", "no energy")
    c = np.cumsum(S) / tot
    k = min(int(np.searchsorted(c, BANDWIDTH_FRACTION)), S.size - 1)
    return _result(float(k * (sr / 2.0) / (S.size - 1) / 1000.0), "C",
                   note="sanity instrument, never a quality score. ⛔ MEASURED "
                        "BLIND to roll-off at BANDWIDTH_FRACTION=0.99 (2.250 kHz "
                        "for untouched AND 4 kHz-limited audio) - it is NOT the "
                        "domain predicate; see validated_support().")


